/**
 * interview-project-manager.ts — 多角色访谈项目管理器
 *
 * P2-18: 7 个 Agent 工具，管理从项目创建到证据聚合的完整访谈生命周期。
 *
 * 工具清单：
 *   1. create_interview_project   — 创建访谈项目（范围、受访者、通道）
 *   2. get_interviewee_profile    — 获取/构建角色画像
 *   3. generate_questionnaire     — 基于角色+领域生成定制问卷
 *   4. manage_interview_session   — 管理访谈会话状态
 *   5. distribute_survey          — 发放匿名问卷
 *   6. aggregate_findings         — 按角色权重聚合多通道发现
 *   7. get_project_progress       — 查询项目进度
 *
 * 对标 Claw-Code 模式：
 *   - 每个工具是纯函数，输入→输出，独立可测试
 *   - 工具间通过 InterviewProject 状态对象通信
 *   - 所有状态操作返回新对象（不可变更新）
 */
import type { IntervieweeProfile } from './interviewee-profile';
export type InterviewChannel = 'one_on_one' | 'anonymous_survey' | 'focus_group' | 'document_review' | 'system_collection';
export type InterviewRole = 'c_suite' | 'vp_director' | 'manager' | 'individual' | 'external';
export type SessionStatus = 'pending' | 'in_progress' | 'completed' | 'skipped' | 'declined';
export type ProjectPhase = 'setup' | 'collection' | 'analysis' | 'complete';
export interface Interviewee {
    id: string;
    name: string;
    role: InterviewRole;
    title: string;
    department: string;
    tenure: string;
    channels: InterviewChannel[];
    status: SessionStatus;
    profile?: IntervieweeProfile;
    scheduledAt?: string;
    completedAt?: string;
}
export interface InterviewProject {
    id: string;
    teamId: string;
    name: string;
    phase: ProjectPhase;
    scope: {
        dimensions: string[];
        depth: 'quick' | 'standard' | 'deep';
        maxInterviewees: number;
        anonymityRules: {
            surveyResponses: boolean;
            quotes: boolean;
            aggregationThreshold: number;
        };
    };
    interviewees: Interviewee[];
    channels: {
        type: InterviewChannel;
        enabled: boolean;
        targetCount: number;
        completedCount: number;
    }[];
    createdAt: string;
    updatedAt: string;
}
export interface CreateProjectInput {
    teamId: string;
    name: string;
    dimensions?: string[];
    depth?: 'quick' | 'standard' | 'deep';
    maxInterviewees?: number;
    channels?: InterviewChannel[];
}
export interface AddIntervieweeInput {
    projectId: string;
    name: string;
    role: InterviewRole;
    title: string;
    department: string;
    tenure?: string;
    channels?: InterviewChannel[];
}
export interface GenerateQuestionnaireInput {
    projectId: string;
    intervieweeId?: string;
    domains?: string[];
    questionCount?: number;
}
export interface QuestionnaireResult {
    intervieweeId?: string;
    role?: InterviewRole;
    questions: Array<{
        id: string;
        text: string;
        domain: string;
        sensitivity: string;
        suggestedChannel: InterviewChannel;
    }>;
    estimatedMinutes: number;
}
export interface SessionUpdateInput {
    projectId: string;
    intervieweeId: string;
    status: SessionStatus;
    notes?: string;
}
export interface AggregateInput {
    projectId: string;
    dimensions?: string[];
    roleWeights?: Record<InterviewRole, number>;
    minConfidence?: number;
}
export interface AggregatedFinding {
    dimension: string;
    score: number;
    confidence: number;
    sourceCount: number;
    roleBreakdown: Record<string, number>;
    contradictions: string[];
    topQuotes: string[];
}
export interface ProjectProgress {
    projectId: string;
    phase: ProjectPhase;
    totalInterviewees: number;
    completedSessions: number;
    declinedSessions: number;
    surveyResponseRate: number;
    documentQueueSize: number;
    dataCompleteness: number;
    nextRecommendedAction: string;
}
export interface CreateProjectResult {
    project: InterviewProject;
    recommendations: string[];
}
export declare function createInterviewProject(input: CreateProjectInput): CreateProjectResult;
export declare function getIntervieweeProfile(projectId: string, intervieweeId: string): IntervieweeProfile | null;
export declare function generateQuestionnaire(input: GenerateQuestionnaireInput): QuestionnaireResult;
export interface SessionResult {
    interviewee: Interviewee;
    projectPhase: ProjectPhase;
    completedCount: number;
    totalCount: number;
}
export declare function updateInterviewSession(input: SessionUpdateInput): SessionResult | null;
export interface SurveyDistribution {
    projectId: string;
    surveyIds: string[];
    targetRoles: InterviewRole[];
    anonymousLink: string;
    message: string;
}
export declare function distributeSurvey(projectId: string, baseUrl?: string): SurveyDistribution | null;
export declare function aggregateFindings(input: AggregateInput): AggregatedFinding[];
export declare function getProjectProgress(projectId: string): ProjectProgress | null;
export declare function addInterviewee(projectId: string, input: AddIntervieweeInput): Interviewee | null;
/** 根据团队规模推荐通道组合 */
export declare function recommendChannels(teamSize: number): InterviewChannel[];
/** 获取项目（用于测试和调试） */
export declare function getProject(projectId: string): InterviewProject | undefined;
/** 清空存储（测试用） */
export declare function clearProjectStore(): void;
